def main():
    sim = Simulation(MODEL_PLAN)
    sim.run()
    results = {
        "time_series": sim.time_series,
        "simulation_metrics": sim.additional_outputs,
    }
    # Fail fast if outputs are empty
    if not sim.time_series.get("adoption_rate"):
        raise RuntimeError("No time series produced. Check run loop and data loading.")
    # Optionally, save to file or print
    print(json.dumps(results))

def _compute_peer_rates_agg(self) -> Dict[int, float]:
    rates: Dict[int, float] = {}
    for aid in self.all_nodes:
        num = 0.0
        den = 0.0
        for ln in self.layer_names:
            nbrs = self.layer_adj[ln].get(aid, set())
            if not nbrs:
                continue
            masked = sum(1 for v in nbrs if self.agents.get(v, None) and self.agents[v].mask_wearing)
            layer_rate = masked / max(1, len(nbrs))
            w = self.layer_weights.get(ln, 1.0)
            num += w * layer_rate
            den += w
        rates[aid] = clip01(num / den) if den > 0 else 0.0
    return rates

def _record_metrics(self, t: int, new_adopters: set) -> None:
    adoption_rate = sum(1 for a in self.agents.values() if a.mask_wearing) / max(1, len(self.agents))
    self.time_series.setdefault("adoption_rate", []).append(adoption_rate)
    # Assortativity on union graph
    try:
        G = nx.Graph()
        for ln in self.layer_names:
            for (u, v) in self.ties[ln].keys():
                G.add_edge(u, v)
        nx.set_node_attributes(G, {aid: int(self.agents[aid].mask_wearing) for aid in self.agents}, "adopt")
        assort = nx.attribute_assortativity_coefficient(G, "adopt") if G.number_of_edges() > 0 else 0.0
    except Exception:
        assort = 0.0
    self.time_series.setdefault("assortativity_of_adoption", []).append(assort)
    # Time to threshold
    if adoption_rate >= self.adoption_target and "time_to_threshold" not in self.additional_outputs:
        self.additional_outputs["time_to_threshold"] = t
    # Track new adoptions for behavioral R0/exposures
    self.daily_new_adoptions.append(new_adopters)

def _maybe_calibrate_from_train(self) -> None:
    data_root = os.path.join(PROJECT_ROOT, self.model_plan.get("data_folder", ""))
    train_file = os.path.join(data_root, "train_data.csv")
    df = self._load_train_data(train_file)
    if df is None:
        return
    # Simple population-level calibration fallback: tune intercept to match day-0 rate
    try:
        day0 = df[df["day"] == 0]
        if not day0.empty:
            y0 = day0["wearing_mask"].astype(int).mean()
            # Adjust theta_intercept so initial sigmoid close to y0
            if 0 < y0 < 1:
                self.theta_intercept = math.log(y0/(1-y0)) - 0.5  # rough adjustment
    except Exception:
        pass

def _compute_holdout_rmse(self) -> None:
    data_root = os.path.join(PROJECT_ROOT, self.model_plan.get("data_folder", ""))
    train_file = os.path.join(data_root, "train_data.csv")
    df = self._load_train_data(train_file)
    if df is None or not self.time_series.get("adoption_rate"):
        return
    # Aggregate actual adoption by day for days 30-39
    holdout = df[(df["day"] >= 30) & (df["day"] <= 39)]
    if holdout.empty:
        return
    actual_by_day = holdout.groupby("day")["wearing_mask"].mean().reindex(range(30, 40), fill_value=np.nan)
    sim_by_day = self.time_series["adoption_rate"][0:len(actual_by_day)]
    if len(sim_by_day) >= 40:  # ensure we ran full period
        sim_holdout = self.time_series["adoption_rate"][30:40]
        actual = [float(x) for x in actual_by_day.values]
        if not any(np.isnan(actual)):
            self.additional_outputs["RMSE_adoption_rate_holdout_days_30_39"] = rmse(actual, sim_holdout)
